// An agent is protected when its enforcement module is running and its effective operating mode is Enforcing
// (same rules Centra uses; an Unset mode falls back to the agent's default operating mode).
let IsProtected = (health: dynamic, configuration: dynamic) {
    let status = toupper(tostring(health.enforcement_agent.status));
    let mode = tostring(configuration.enforcementagent.agent_operating_mode);
    isnotempty(status)
    and status !in ("DISABLED", "NOT_INSTALLED", "ERROR", "STOPPED", "ASSETSHUTDOWN", "STOPPING", "UNKNOWN")
    and iff(mode in ("", "Unset"),
            coalesce(toint(health.enforcement_agent.default_operating_mode), 3) !in (1, 2),
            mode == "Enforcing")
};
// Bucket size follows the selected time range (polls arrive every 10 minutes).
let range_len = {TimeRange:end} - {TimeRange:start};
let step = case(range_len <= 4h, 10m, range_len <= 1d, 1h, range_len <= 3d, 6h, 1d);
let per_bucket = GuardicoreAgents_CL
| where TimeGenerated {TimeRange}
| extend bucket = bin(TimeGenerated, step)
| summarize arg_max(TimeGenerated, health, configuration) by id, bucket   // last state of each agent per bucket
| summarize Protected = countif(IsProtected(health, configuration)), Total = count() by bucket;
let has_data = toscalar(per_bucket | count) > 0;
range bucket from bin({TimeRange:start}, step) to {TimeRange:end} step step
| where has_data
| join kind=leftouter (per_bucket) on bucket
| project Time = iff(step < 1d, format_datetime(bucket, "yyyy-MM-dd HH:mm"), format_datetime(bucket, "yyyy-MM-dd")),
          Protected = coalesce(Protected, 0),
          ['Not protected'] = coalesce(Total, 0) - coalesce(Protected, 0)
| order by Time asc

let range_len = {TimeRange:end} - {TimeRange:start};
let step = case(range_len <= 4h, 10m, range_len <= 1d, 1h, range_len <= 3d, 6h, 1d);
let per_bucket = GuardicoreAssets_CL
| where TimeGenerated {TimeRange}
| extend bucket = bin(TimeGenerated, step)
| summarize arg_max(TimeGenerated, is_on, status, is_agent_installed, agent_id) by id, bucket   // last state per asset per bucket
| where coalesce(is_on, status =~ "on")
| summarize WithAgent = countif(coalesce(is_agent_installed, false) or isnotempty(agent_id)), Total = count() by bucket;
let has_data = toscalar(per_bucket | count) > 0;
range bucket from bin({TimeRange:start}, step) to {TimeRange:end} step step
| where has_data
| join kind=leftouter (per_bucket) on bucket
| project Time = iff(step < 1d, format_datetime(bucket, "yyyy-MM-dd HH:mm"), format_datetime(bucket, "yyyy-MM-dd")),
          ['With agent'] = coalesce(WithAgent, 0),
          ['Without agent'] = coalesce(Total, 0) - coalesce(WithAgent, 0)
| order by Time asc

// latest state of each asset; "with agent" = Centra is_agent_installed (or a linked agent id)
let AssetState = (t: datetime, e: datetime) {
    GuardicoreAssets_CL
    | where TimeGenerated between (t .. e)
    | summarize arg_max(TimeGenerated, is_on, status, is_agent_installed, agent_id, first_seen, last_seen,
                        name, vm_name, full_name, comments) by id
    | extend PoweredOn = coalesce(is_on, status =~ "on"),
             HasAgent = coalesce(is_agent_installed, false) or isnotempty(agent_id),
             Name = coalesce(name, vm_name, full_name, id)
};
let range_len = {TimeRange:end} - {TimeRange:start};
let step = case(range_len <= 4h, 10m, range_len <= 1d, 1h, range_len <= 3d, 6h, 1d);
let new_assets = AssetState({TimeRange:start}, {TimeRange:end})
| extend discovered = unixtime_milliseconds_todatetime(tolong(first_seen))
| where discovered between ({TimeRange:start} .. {TimeRange:end})
| summarize WithAgent = countif(HasAgent), WithoutAgent = countif(not(HasAgent)) by bucket = bin(discovered, step);
let has_data = toscalar(new_assets | count) > 0;
range bucket from bin({TimeRange:start}, step) to {TimeRange:end} step step
| where has_data
| join kind=leftouter (new_assets) on bucket
| project Time = iff(step < 1d, format_datetime(bucket, "yyyy-MM-dd HH:mm"), format_datetime(bucket, "yyyy-MM-dd")),
          ['With agent'] = coalesce(WithAgent, 0),
          ['Without agent'] = coalesce(WithoutAgent, 0)
| order by Time asc
